ticker.vanilla:
// Live ticker, plain DOM (hand-optimized): the rows are cloned from one prototype, the price cells are kept in an
// array, and a tick writes only the changed cells' text and class.
import { fmtPrice, dir, type Quote, type Tick } from "../core.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const doc = host.ownerDocument
  const table = doc.createElement("table"), tbody = doc.createElement("tbody")
  table.className = "bt"
  const proto = doc.createElement("tr")
  const sym = doc.createElement("td"), px = doc.createElement("td")
  sym.className = "sym"; px.className = "px"
  sym.append(""); px.append("")
  proto.append(sym, px)
  const cells: Text[] = [], tds: HTMLElement[] = [], last = data.map((q) => q.price)
  for (const q of data) {
    const tr = proto.cloneNode(true) as HTMLTableRowElement
    ;(tr.firstChild!.firstChild as Text).data = q.sym
    const td = tr.lastChild as HTMLElement
    ;(td.firstChild as Text).data = fmtPrice(q.price)
    cells.push(td.firstChild as Text); tds.push(td)
    tbody.append(tr)
  }
  table.append(tbody)
  host.append(table)
  return {
    step: (p) => {
      for (const t of p as Tick[]) {
        cells[t.i]!.data = fmtPrice(t.price)
        tds[t.i]!.className = `px ${dir(t.price, last[t.i]!)}`
        last[t.i] = t.price
      }
    },
    destroy: () => table.remove(),
  }
}

ticker.march:
// Live ticker, HADI March: each quote holds two signals (price and direction); a tick writes them inside batch(), and
// only the bound text and class of the changed cells update. No list diff: the rows themselves never change.
import { render, signal, batch } from "hadi-march"
import { fmtPrice, dir, type Quote, type Tick, type ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const rows = data.map((q) => ({ sym: q.sym, price: signal(q.price), cls: signal("px") }))
  const dispose = render(() => <table class="bt"><tbody>
    {rows.map((r) => <tr><td class="sym">{r.sym}</td><td class={r.cls()}>{fmtPrice(r.price())}</td></tr>)}
  </tbody></table>, host)
  return {
    step: (p) => batch(() => {
      for (const t of p as Tick[]) {
        const r = rows[t.i]!
        r.cls.set(`px ${dir(t.price, r.price.peek())}`)
        r.price.set(t.price)
      }
    }),
    destroy: dispose,
  }
}

ticker.react:
// Live ticker, React 19, with the pattern React recommends for frequent updates to a few items of a large list:
// state split per row (a small external store, one useSyncExternalStore subscription per memo row), so a tick
// re-renders only the changed rows and the list component itself does not render again. Updates run in flushSync.
import { createElement as h, memo, useSyncExternalStore } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { fmtPrice, dir, type Quote, type Tick, type ScenarioApp } from "../core.ts"

interface Cell { price: number; cls: string }
export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const cells: Cell[] = data.map((q) => ({ price: q.price, cls: "px" }))
  const subs: ((() => void) | null)[] = data.map(() => null)
  const Row = memo(function Row({ i, sym }: { i: number; sym: string }) {
    const c = useSyncExternalStore((cb) => { subs[i] = cb; return () => { subs[i] = null } }, () => cells[i]!)
    return h("tr", null, h("td", { className: "sym" }, sym), h("td", { className: c.cls }, fmtPrice(c.price)))
  })
  const App = () => h("table", { className: "bt" }, h("tbody", null, data.map((q, i) => h(Row, { key: q.id, i, sym: q.sym }))))
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => flushSync(() => {
      for (const t of p as Tick[]) {
        cells[t.i] = { price: t.price, cls: `px ${dir(t.price, cells[t.i]!.price)}` }
        subs[t.i]?.()
      }
    }),
    destroy: () => root.unmount(),
  }
}

ticker.preact:
// Live ticker, Preact 10: state split per row. Each row is a class component holding its own price; a tick calls
// setState on the changed rows only (the list does not render again). Preact renders in a microtask, before the paint.
import { h, render, Component } from "preact"
import { fmtPrice, dir, type Quote, type Tick, type ScenarioApp } from "../core.ts"

interface RowState { price: number; cls: string }
export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const rows: (RowView | null)[] = data.map(() => null)
  class RowView extends Component<{ i: number; q: Quote }, RowState> {
    constructor(p: { i: number; q: Quote }) { super(p); this.state = { price: p.q.price, cls: "px" }; rows[p.i] = this }
    override shouldComponentUpdate(_p: unknown, s: RowState) { return s.price !== this.state.price || s.cls !== this.state.cls }
    render({ q }: { q: Quote }, { price, cls }: RowState) { return h("tr", null, h("td", { class: "sym" }, q.sym), h("td", { class: cls }, fmtPrice(price))) }
  }
  render(h("table", { class: "bt" }, h("tbody", null, data.map((q, i) => h(RowView, { key: q.id, i, q })))), host)
  return {
    step: (p) => {
      for (const t of p as Tick[]) {
        const r = rows[t.i]!
        r.setState({ price: t.price, cls: `px ${dir(t.price, r.state.price)}` })
      }
    },
    destroy: () => render(null, host),
  }
}

ticker.vue:
// ── vue-row.template.html
<tr><td class="sym">{{ r.sym }}</td><td :class="r.cls">{{ fmt(r.price) }}</td></tr>

// ── vue.template.html
<table class="bt"><tbody>
  <TickerRow v-for="r of rows" :key="r.id" :r="r" />
</tbody></table>

// ── vue.ts
// Live ticker, Vue 3: each quote is a reactive object rendered by its own row component (templates compiled ahead of
// time by Vue's compiler: vue.template.html, vue-row.template.html → *.render.gen.js). Changing a quote re-renders only
// its row component; the list is a plain array and does not render again. Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, markRaw } from "vue"
import { render as listRender } from "./vue.render.gen.js"
import { render as rowRender } from "./vue-row.render.gen.js"
import { fmtPrice, dir, type Quote, type Tick, type ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const rows = markRaw(data.map((q) => reactive({ id: q.id, sym: q.sym, price: q.price, cls: "px" })))
  const TickerRow = defineComponent({ props: { r: { type: Object, required: true } }, setup: () => ({ fmt: fmtPrice }), render: rowRender })
  const App = defineComponent({ components: { TickerRow }, setup: () => ({ rows }), render: listRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => {
      for (const t of p as Tick[]) {
        const r = rows[t.i]!
        r.cls = `px ${dir(t.price, r.price)}`
        r.price = t.price
      }
    },
    destroy: () => app.unmount(),
  }
}

ticker.solid:
// Live ticker, SolidJS: each quote holds two signals (price and class); a tick sets them inside batch() and Solid
// updates only the bound text and class. Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, batch } from "solid-js"
import { render } from "solid-js/web"
import { fmtPrice, dir } from "../core.ts"

export function mount(host, data) {
  const rows = data.map((q) => { const [price, setPrice] = createSignal(q.price), [cls, setCls] = createSignal("px"); return { sym: q.sym, price, setPrice, cls, setCls } })
  const dispose = render(() => (
    <table class="bt"><tbody>
      {rows.map((r) => <tr><td class="sym">{r.sym}</td><td class={r.cls()}>{fmtPrice(r.price())}</td></tr>)}
    </tbody></table>
  ), host)
  return {
    step: (ticks) => batch(() => { for (const t of ticks) { const r = rows[t.i]; r.setCls(`px ${dir(t.price, r.price())}`); r.setPrice(t.price) } }),
    destroy: dispose,
  }
}

ticker.lit:
// Live ticker, Lit 3: the usual Lit pattern, a render() of the whole list per tick; lit-html walks every row's values
// and touches the DOM only where a value changed (no virtual DOM, but a value check per row). Row template in compiled
// form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, attr, child } from "../lit-tpl.ts"
import { fmtPrice, dir, type Quote, type Tick, type ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const row = template(el("tr", {}, el("td", { class: "sym" }, child()), el("td", { class: attr("class") }, child())))
  const rows = data.map((q) => ({ sym: q.sym, price: q.price, cls: "px" }))
  const table = document.createElement("table"), tbody = document.createElement("tbody")
  table.className = "bt"; table.append(tbody); host.append(table)
  const draw = () => render(rows.map((r) => row(r.sym, r.cls, fmtPrice(r.price))), tbody)
  draw()
  return {
    step: (p) => {
      for (const t of p as Tick[]) { const r = rows[t.i]!; r.cls = `px ${dir(t.price, r.price)}`; r.price = t.price }
      draw()
    },
    destroy: () => { render(null, tbody); table.remove() },
  }
}
